import { styled } from '@hexa-ui/theme';

export const StyledEmbeddedBigNumbersWrapper = styled('div', {
  position: 'relative',
  zIndex: 0,
  isolation: 'isolate',
});

export const StyledBigNumbersContainer = styled('div', {
  display: 'flex',
  gap: '16px',

  '& > div': {
    maxWidth: '300px',
  },
});
